import{_ as s}from"./chunks/Audio.COine8Wh.js";import{_ as a}from"./chunks/Tags.BJ536pW3.js";import{c as n,o,j as i,G as t,ae as r,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const m=JSON.parse('{"title":"Guiding and Establishing National Innovation for U.S. Stablecoins Act","description":"","frontmatter":{"legisId":"2025-07-18-guiding-and-establishing-national-innovation-for-us-stablecoins-act","title":"Guiding and Establishing National Innovation for U.S. Stablecoins Act","displayTitle":"Guiding and Establishing National Innovation for U.S. Stablecoins Act","lawNumber":"119-27","billNumber":"S. 1582","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ27.xml","publishDate":"2025-07-18T00:00:00-05:00","industries":["finance","technology","government-operations"],"agencies":["Office of the Comptroller of the Currency"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Guiding and Establishing National Innovation for U.S. Stablecoins Act\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-07-18-guiding-and-establishing-national-innovation-for-us-stablecoins-act\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Guiding and Establishing National Innovation for U.S. Stablecoins Act\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-07-18-guiding-and-establishing-national-innovation-for-us-stablecoins-act\\",\\"datePublished\\":\\"2025-07-18T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-07-18-guiding-and-establishing-national-innovation-for-us-stablecoins-act\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-07-18-guiding-and-establishing-national-innovation-for-us-stablecoins-act.md","filePath":"congress-bills/2025-07-18-guiding-and-establishing-national-innovation-for-us-stablecoins-act.md","lastUpdated":1788887623000}'),d={name:"congress-bills/2025-07-18-guiding-and-establishing-national-innovation-for-us-stablecoins-act.md"},h=Object.assign(d,{setup(c){return(u,e)=>(o(),n("div",null,[e[0]||(e[0]=i("h1",{id:"guiding-and-establishing-national-innovation-for-u-s-stablecoins-act",tabindex:"-1"},[l("Guiding and Establishing National Innovation for U.S. Stablecoins Act "),i("a",{class:"header-anchor",href:"#guiding-and-establishing-national-innovation-for-u-s-stablecoins-act","aria-label":'Permalink to "Guiding and Establishing National Innovation for U.S. Stablecoins Act"'},"​")],-1)),t(s),t(a,{list:"/congress-bills"}),e[1]||(e[1]=r('<p>Signed into law on Friday, July 18, 2025. Public Law 119-27, S. 1582.</p><p><strong>Headline:</strong> The GENIUS Act creates federal and state rules for issuing, backing, supervising, and using payment stablecoins.</p><p><strong>Why it matters:</strong> The law limits the U.S. stablecoin market to approved issuers, requires liquid reserves and disclosures, and protects holders if an issuer fails. It also sets operating rules for banks, state-chartered institutions, and qualifying foreign issuers.</p><p><strong>What the law does:</strong></p><ul><li>Restricts stablecoin issuance and U.S. distribution to approved federal, state, or qualifying foreign issuers.</li><li>Requires issuers to maintain dollar-for-dollar liquid reserves, publish monthly reserve information, disclose redemption terms, and undergo accounting reviews.</li><li>Imposes anti-money-laundering, customer identification, sanctions, monitoring, and lawful-order requirements.</li><li>Prohibits issuers from paying interest solely for holding stablecoins or marketing them as federally guaranteed, approved, or insured.</li><li>Gives regulators licensing, supervision, corrective-action, removal, and penalty powers, while prioritizing holders’ claims to reserves during insolvency.</li><li>Preserves lawful digital-asset activities by banks, credit unions, and trust companies and limits balance-sheet and capital treatment of customer assets held in custody.</li><li>Excludes qualifying payment stablecoins from specified federal securities, commodities, and investment-company treatment.</li><li>Allows qualifying state-chartered institutions to provide certain stablecoin services across state lines, subject to host-state consumer protection enforcement.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Stablecoin issuers, digital-asset service providers, custodians, and their executives.</li><li>Banks, credit unions, trust companies, and qualifying state-chartered financial institutions.</li><li>Stablecoin holders, customers, and qualifying foreign issuers seeking access to the U.S. market.</li><li>Federal and state financial regulators responsible for approval, supervision, enforcement, and implementing rules.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Stablecoins offered in the United States must generally come from approved issuers and be backed one-for-one by specified liquid reserves.</li><li>Holders receive reserve and redemption disclosures, priority claims to required reserves if an issuer fails, and notice that stablecoins lack federal insurance or guarantees.</li></ul><p><strong>Context:</strong> The law takes effect on the earlier of 18 months after enactment or 120 days after federal regulators issue final implementing regulations.</p><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="guiding-and-establishing-national-innovation-for-u-s-stablecoins-act-part-1-of-2" tabindex="-1">Guiding and Establishing National Innovation for U.S. Stablecoins Act (part 1 of 2) <a class="header-anchor" href="#guiding-and-establishing-national-innovation-for-u-s-stablecoins-act-part-1-of-2" aria-label="Permalink to &quot;Guiding and Establishing National Innovation for U.S. Stablecoins Act (part 1 of 2)&quot;">​</a></h3><p>This part of the GENIUS Act creates a federal and state regulatory framework for payment stablecoins offered in the United States. It limits issuance to approved issuers, requires full backing with specified liquid reserves, establishes disclosure and compliance duties, and gives regulators licensing, supervision, and enforcement powers. It also protects stablecoin holders and customer assets during custody and insolvency and sets rules for foreign issuers, anti-money-laundering controls, interoperability, studies, and reports.</p><p><strong>Key takeaways:</strong></p><ul><li>Only approved federal or state issuers may issue payment stablecoins in the United States, and digital asset service providers generally may not offer unapproved stablecoins to people in the United States.</li><li>Permitted issuers must maintain at least one dollar of specified liquid reserves for each dollar of stablecoins outstanding, publish monthly reserve information, provide clear redemption terms, and obtain monthly accounting review and executive certification.</li><li>Issuers must follow anti-money-laundering, customer identification, sanctions, transaction-monitoring, and lawful-order requirements, and they may not pay interest or yield solely for holding a stablecoin.</li><li>Stablecoins are not backed or guaranteed by the United States and are not covered by federal deposit or credit union share insurance, and issuers may not market them as government-issued, government-approved, or insured.</li><li>State-regulated issuers may operate under certified state frameworks when outstanding issuance does not exceed $10 billion, while larger issuers generally must transition to joint federal oversight unless granted a waiver.</li><li>Regulators may deny, suspend, or revoke approval, order corrective action, remove responsible officials, and impose civil or criminal penalties for violations, while stablecoin holders receive priority claims to required reserves if an issuer becomes insolvent.</li></ul><h3 id="guiding-and-establishing-national-innovation-for-u-s-stablecoins-act-part-2-of-2" tabindex="-1">Guiding and Establishing National Innovation for U.S. Stablecoins Act (part 2 of 2) <a class="header-anchor" href="#guiding-and-establishing-national-innovation-for-u-s-stablecoins-act-part-2-of-2" aria-label="Permalink to &quot;Guiding and Establishing National Innovation for U.S. Stablecoins Act (part 2 of 2)&quot;">​</a></h3><p>This part preserves banks’ and credit unions’ authority to conduct lawful digital-asset and stablecoin activities, sets accounting and capital rules for assets held in custody, and allows qualifying state-chartered institutions to offer stablecoin-related services across states. It also excludes qualifying payment stablecoins from federal securities and commodities definitions, establishes conditions for foreign stablecoin issuers to operate in the United States, and sets the Act’s effective date.</p><p><strong>Key takeaways:</strong></p><ul><li>Banks, credit unions, and trust companies may continue lawful activities such as issuing digital representations of deposits, using distributed ledgers, and providing stablecoin custody services.</li><li>Federal regulators must clarify that regulated entities may conduct the stablecoin activities and investments authorized by the Act.</li><li>Financial institutions generally cannot be required to record customer-owned digital assets held in custody as their own liabilities or maintain capital against them, except as needed to address custody-related operational risks.</li><li>Qualifying state-chartered institutions with permitted stablecoin-issuing subsidiaries may provide money transmission and custody services in other states, while host-state regulators retain authority to enforce applicable consumer protection laws.</li><li>Payment stablecoins issued by permitted issuers are not treated as securities or commodities under the listed federal laws, and permitted issuers are excluded from investment company treatment.</li><li>Foreign stablecoin issuers may access the U.S. market if they are comparably regulated, register with the Comptroller, satisfy applicable U.S. reserve requirements, and do not operate from sanctioned or high-risk jurisdictions.</li><li>Payment stablecoin holdings of $5,000 or less are excluded from the specified federal financial disclosure requirement.</li><li>The Act takes effect on the earlier of 18 months after enactment or 120 days after federal regulators issue final implementing regulations.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ27.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ27.xml</a></p>',20))]))}});export{m as __pageData,h as default};
